import{_ as e,o,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"BXC - An Architecture for Lazy RBD Imaging and Snapshot Exports","description":"","frontmatter":{"title":"BXC - An Architecture for Lazy RBD Imaging and Snapshot Exports","date":"2026-04-20T00:00:00.000Z","updated":"2026-04-21T00:00:00.000Z","tags":["RBD","block storage","snapshots","Ceph","差量备份"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/BXC_-_An_Architecture_for_Lazy_RBD_Imaging_and_Snapshot_Exports.md","filePath":"posts/2026/BXC_-_An_Architecture_for_Lazy_RBD_Imaging_and_Snapshot_Exports.md","lastUpdated":1780459816000}'),l={name:"posts/2026/BXC_-_An_Architecture_for_Lazy_RBD_Imaging_and_Snapshot_Exports.md"};function r(n,a,s,h,c,p){return o(),t("div",null,[...a[0]||(a[0]=[i('<h2 id="演讲背景" tabindex="-1">演讲背景 <a class="header-anchor" href="#演讲背景" aria-label="Permalink to &quot;演讲背景&quot;">​</a></h2><p>本次演讲由 Digital Ocean 的工程经理 Kam Saleem 与高级存储工程师 Alicia Casey 联合呈现。Digital Ocean 是全球最大的 Ceph 部署方之一，拥有分布在 16 个区域的约 40 个集群，涵盖 RBD block storage 和 RGW object storage 两类业务。</p><p>随着越来越多的 VM 用户希望将本地 NVMe 资源留给高性能业务，而将 OS 启动盘迁移到 RBD volumes 上，Digital Ocean 面临了大规模 RBD 镜像写入与 snapshot 备份的工程挑战，并为此设计了名为 <strong>Block Exchange（BXC）</strong> 的架构。</p><h2 id="核心问题-rbd-镜像写入的三种传统方案及其缺陷" tabindex="-1">核心问题：RBD 镜像写入的三种传统方案及其缺陷 <a class="header-anchor" href="#核心问题-rbd-镜像写入的三种传统方案及其缺陷" aria-label="Permalink to &quot;核心问题：RBD 镜像写入的三种传统方案及其缺陷&quot;">​</a></h2><h3 id="方案一-clone-保留-golden-image" tabindex="-1">方案一：Clone +保留 golden image <a class="header-anchor" href="#方案一-clone-保留-golden-image" aria-label="Permalink to &quot;方案一：Clone +保留 golden image&quot;">​</a></h3><p>将所有 VM 启动盘设为同一个 golden RBD image 的 clone。问题在于：</p><ul><li>所有 VM 都依赖同一个 snapshot，一旦该 snapshot 损坏，整棵依赖树全部受影响。</li><li>Ceph 支持无限长的 snapshot chain，导致 golden image 无法删除，管理极为困难。</li></ul><h3 id="方案二-clone-flatten" tabindex="-1">方案二：Clone + Flatten <a class="header-anchor" href="#方案二-clone-flatten" aria-label="Permalink to &quot;方案二：Clone + Flatten&quot;">​</a></h3><p>Clone 后立即 flatten，彻底解除依赖。问题在于：</p><ul><li>Digital Ocean 采用 3x replication，大规模 VM 批量创建时，flatten 操作会产生巨量写流量。</li><li>以 50 GB镜像批量创建 1000 台 VM 为例，会产生约 15 TB 的 RBD 写流量，严重竞争运行时 IO。</li></ul><h3 id="方案三-实时从-image-server拉取并-import" tabindex="-1">方案三：实时从 image server拉取并 import <a class="header-anchor" href="#方案三-实时从-image-server拉取并-import" aria-label="Permalink to &quot;方案三：实时从 image server拉取并 import&quot;">​</a></h3><p>每次创建 VM 时直接从 image server 拉取并执行 <code>rbd import</code>。问题在于：</p><ul><li>没有 deduplication，大量重复数据反复在网络上传输，带宽浪费严重。</li></ul><h2 id="bxc-架构设计-lazy-rbd-imaging" tabindex="-1">BXC 架构设计：Lazy RBD Imaging <a class="header-anchor" href="#bxc-架构设计-lazy-rbd-imaging" aria-label="Permalink to &quot;BXC 架构设计：Lazy RBD Imaging&quot;">​</a></h2><h3 id="核心思路" tabindex="-1">核心思路 <a class="header-anchor" href="#核心思路" aria-label="Permalink to &quot;核心思路&quot;">​</a></h3><p>利用 Ceph 的 <strong>RBD import-only live migration</strong> 特性，将 RBD volume 的 parent设置为一个 HTTP server，从而实现按需（on-demand）拉取 block 数据，同时在后台异步完成完整镜像写入。</p><h3 id="镜像存储层" tabindex="-1">镜像存储层 <a class="header-anchor" href="#镜像存储层" aria-label="Permalink to &quot;镜像存储层&quot;">​</a></h3><p>Digital Ocean 的 image store 构建在 S3 之上，每个镜像不以原始文件或 ISO 存储，而是切分为若干 1 MB 的 snappy 压缩 block，支持层级（layer）元数据，类似 OCI image registry的分层结构。</p><h3 id="前端-http-server-block-image-daemon" tabindex="-1">前端 HTTP Server（Block Image Daemon） <a class="header-anchor" href="#前端-http-server-block-image-daemon" aria-label="Permalink to &quot;前端 HTTP Server（Block Image Daemon）&quot;">​</a></h3><p>在 image store 前部署一个 HTTP server，负责：</p><ul><li>接收来自 librbd 的 HTTP range request（由 RBD live migration 机制触发）。</li><li>对请求的 extent 进行解压缩（snappy decompression）。</li><li>对已请求过的 extent 进行 edge cache，实现 deduplication。</li><li>将数据回写到 RBD volume。</li></ul><h3 id="启动流程" tabindex="-1">启动流程 <a class="header-anchor" href="#启动流程" aria-label="Permalink to &quot;启动流程&quot;">​</a></h3><ol><li>用户请求创建启动盘，指定目标镜像。</li><li>BXC 调用 <code>migration prepare import</code>，将 RBD volume 的 parent 配置为指向该镜像的 HTTP server 地址。</li><li>VM 立即可以启动，OS 按需请求 block，librbd 将请求转换为 HTTP range request，由 HTTP server 实时响应。</li><li>后台同时触发 <code>migration execute</code>，异步完成完整镜像的 lazy imaging。</li><li>迁移完成后，通过 status polling 确认状态，执行 commit。</li></ol><h3 id="技术收益" tabindex="-1">技术收益 <a class="header-anchor" href="#技术收益" aria-label="Permalink to &quot;技术收益&quot;">​</a></h3><ul><li><strong>即时启动（instant boot）</strong>：OS 只需请求启动所需的少量 block，无需等待完整镜像写入。</li><li><strong>Deduplication</strong>：已缓存的 extent 不重复传输。</li><li><strong>后台 lazy imaging</strong>：完整数据在后台异步写入，不阻塞用户。</li></ul><h3 id="go-ceph-集成" tabindex="-1">Go-Ceph 集成 <a class="header-anchor" href="#go-ceph-集成" aria-label="Permalink to &quot;Go-Ceph 集成&quot;">​</a></h3><p>Digital Ocean 是 Go 技术栈，整个流程通过 go-ceph 绑定实现：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RADOS connection → open RBD image → migration_prepare_import（指定 HTTP source spec）→ migration_execute → status polling → migration_commit</span></span></code></pre></div><h2 id="bxc-架构设计-差量-rbd-snapshot-备份" tabindex="-1">BXC 架构设计：差量 RBD Snapshot 备份 <a class="header-anchor" href="#bxc-架构设计-差量-rbd-snapshot-备份" aria-label="Permalink to &quot;BXC 架构设计：差量 RBD Snapshot 备份&quot;">​</a></h2><h3 id="传统-ceph-snapshot-的问题" tabindex="-1">传统 Ceph snapshot 的问题 <a class="header-anchor" href="#传统-ceph-snapshot-的问题" aria-label="Permalink to &quot;传统 Ceph snapshot 的问题&quot;">​</a></h3><ul><li>Ceph snapshot 与数据存储在同一 pool 和 cluster，集群故障时 snapshot 与数据同时丢失，不构成真正意义上的备份。</li><li>全量 export浪费存储与带宽。</li><li>依赖 QEMU change tracking 或 NBD metadata 等外部变更追踪机制，增加系统复杂度和故障点。</li></ul><h3 id="差量备份实现流程" tabindex="-1">差量备份实现流程 <a class="header-anchor" href="#差量备份实现流程" aria-label="Permalink to &quot;差量备份实现流程&quot;">​</a></h3><ol><li>列出上一次成功备份的 snapshot。</li><li>对当前数据创建新 snapshot。</li><li>调用 <code>diff_iterate</code>，对比父 snapshot 获取变更的 extent 列表（dirty blocks）。</li><li>调用 <code>read_at</code> 读取这些 extent 的数据。</li><li>通过固定数量的 worker 并发写入目标 image store，形成新的差量 layer。</li><li>Commit 新 layer，删除旧的父 snapshot。</li></ol><p>目标 image store 支持 OCI 风格的层级结构，能够理解 block offset 和 layer 之间的父子关系，与 RBD snapshot chain 的语义保持一致。</p><h3 id="snapshot-chain-管理" tabindex="-1">Snapshot Chain 管理 <a class="header-anchor" href="#snapshot-chain-管理" aria-label="Permalink to &quot;Snapshot Chain 管理&quot;">​</a></h3><p>为避免无限增长的 snapshot chain，Digital Ocean 采用以下策略：</p><ul><li>用户按照配置的备份周期（cadence）保留 snapshot，过期后自动清理。</li><li>后台持续运行 layer 合并（collapse/converge）进程，在过期窗口到期后，判断哪些 block 可以释放，并将其合并到需要保留的 layer 中，而非简单删除旧 block。</li></ul><h3 id="灾难恢复边界" tabindex="-1">灾难恢复边界 <a class="header-anchor" href="#灾难恢复边界" aria-label="Permalink to &quot;灾难恢复边界&quot;">​</a></h3><ul><li><strong>用户侧灾难恢复</strong>：用户误操作导致运行时数据损坏，可通过差量备份恢复。</li><li><strong>基础设施侧灾难恢复</strong>：依赖存储设备自身的 deduplication 能力，或 Ceph 的 3x replication，failure domain 在数据传输链路的另一端。</li></ul><h2 id="bxc-整体架构与编排" tabindex="-1">BXC 整体架构与编排 <a class="header-anchor" href="#bxc-整体架构与编排" aria-label="Permalink to &quot;BXC 整体架构与编排&quot;">​</a></h2><h3 id="架构命名" tabindex="-1">架构命名 <a class="header-anchor" href="#架构命名" aria-label="Permalink to &quot;架构命名&quot;">​</a></h3><p>Block Exchange（BXC）：在 RBD block system 与 image store block system 之间双向交换 block 数据。</p><h3 id="编排层-temporal" tabindex="-1">编排层：Temporal <a class="header-anchor" href="#编排层-temporal" aria-label="Permalink to &quot;编排层：Temporal&quot;">​</a></h3><p>使用 <strong>Temporal</strong> 作为工作流编排引擎，管理两个方向的数据流：</p><ul><li><strong>前端</strong>：gRPC 接口，接收 source URI 和 target URI。</li><li><strong>Worker</strong>：BXC worker 根据 source/target URI 判断数据流方向，触发对应的 Temporal workflow。 <ul><li><strong>备份方向</strong>（RBD → image store）：执行 snapshot、diff_iterate、dirty block export、layer commit流程。</li><li><strong>镜像写入方向</strong>（image store → RBD）：初始化 HTTP server（Block Image Daemon），触发 RBD import-only live migration，并负责 status polling 与 commit。</li></ul></li></ul><h2 id="q-a-摘要" tabindex="-1">Q&amp;A 摘要 <a class="header-anchor" href="#q-a-摘要" aria-label="Permalink to &quot;Q&amp;A 摘要&quot;">​</a></h2><p><strong>Q：差量 snapshot chain 在灾难恢复时的 reconciliation 复杂度如何？</strong></p><p>A：Digital Ocean 通过持续运行的 layer 合并进程来避免无限长的 chain。过期窗口到期后，系统自动判断可释放的 block 并合并到保留 layer，而非依赖手动清理。对于基础设施级别的灾难恢复，依赖存储设备或 Ceph 3x replication 保障，差量系统主要面向用户侧的数据恢复场景。</p><p><strong>Q（演讲者反问）：是否有其他团队在做 RBD volumes 的差量备份？</strong></p><p>现场反应热烈，表明该方案具有较强的参考价值。</p>',50)])])}const m=e(l,[["render",r]]);export{g as __pageData,m as default};
